import json,hashlib
from pathlib import Path
from datetime import datetime,timezone
from pypdf import PdfReader
root=Path('campaigns/toronto-january-2027-jobs');plans=json.load(open(root/'job-plans.json'));at=datetime.now(timezone.utc).isoformat()
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n')
history={'account':'gordienko.adg@gmail.com','observed_at':'2026-09-16T11:44:00Z','source':'Gmail visible all-folders search via browser tab 1964896046','query':'in:anywhere {waabi.ai kepler.space keplercommunications.com ecobee.com peakpowerenergy.com borealisai.com rbcborealis.com}','result':'No exact matches','messages':[],'scope_limit':'Current sending mailbox and named domains/aliases only; unknown aliases, permanently deleted messages and other mailboxes are not covered. Refresh before sending.'}
write(root/'mailbox-check.json',history)
reasons={
 'waabi':{'continuity':'Specific tutorial/opening leads to simulation and recovery work, actual implementation examples, then a bounded January-April Toronto inquiry.','skeptic':'Research opening is real, but January and four-month availability are asked rather than asserted. Sean is technically relevant; no claim he is the hiring manager or Toronto-based. No claim to have watched the tutorial.'},
 'rbc-borealis':{'continuity':'Posted ML software role connects to measured distillation, evaluation and implementation work before the four-month request.','skeptic':'Winter four-month option and Toronto are evidenced. Degree is unchanged; missing data-stack tools are absent. Email does not claim an application was submitted or that Hanieh owns the requisition. Formal transcript requirement remains outstanding.'},
 'kepler':{'continuity':'Real winter opening leads to verification and hardware work, explaining the practical motivation and fit inquiry.','skeptic':'Role and dates/site are confirmed. Resume and email identify robotics/planning experience without claiming embedded Linux or RTOS experience. This is a weaker match due to explicit embedded requirements; the fit question is appropriate, no outcome promised.'},
 'ecobee':{'continuity':'Interest in practical energy/device software connects to physical robotics and outage-data API work, then asks about staffing.','skeptic':'Inquiry is explicitly speculative and does not invent a vacancy. Alan is a routing contact; exact team remains uncertain. No thermostat/firmware expertise, team defect or team need is asserted.'},
 'peak-power':{'continuity':'Forecast-to-dispatch decision links to real planning/optimization and utility-data software, then asks about a four-month role.','skeptic':'Meysam is a relevant data-science contact with a verified work address and documented technical contribution. Headcount and manager authority are unknown. No battery dispatch experience or hiring intent is invented.'}}
all_drafts=[]
for p in plans:
 d=root/'accounts'/p['id'];draft=json.load(open(d/'draft.json'));expected=hashlib.sha256((draft['subject']+'\n'+draft['body']).encode()).hexdigest();assert expected==draft['draft_hash']
 reviews={'draft_hash':expected,'research_sha256':draft['research_sha256'],'reviewed_at':at,'reviewer':'Codex separate full-draft reread after writer output','thought_continuity':{'status':'PASS','reason':reasons[p['id']]['continuity']},'cold_email_skeptic':{'status':'PASS_FOR_LOCAL_REVIEW','reason':reasons[p['id']]['skeptic']},'grammar':'PASS','facts':'Sender facts checked against purple resume; company facts and proposed work are separated.','delivery_status':'No sending or external scheduling authorized. Commute still conditional.'}
 write(d/'outbound-reviews.json',reviews);write(d/'mailbox-check.json',history)
 draft['status']='local_review';draft['reviewed_at']=at;write(d/'draft.json',draft)
 packet=json.load(open(d/'writer-packet.json'));packet['review_pending']=False;write(d/'writer-packet.json',packet)
 resume=json.load(open(d/'resume-tailoring.json'))
 if p['id'] in ['waabi','rbc-borealis','kepler']:
  pdf=Path(resume['output']);r=PdfReader(pdf);assert len(r.pages)==1;assert hashlib.sha256(pdf.read_bytes()).hexdigest()==resume['sha256']
  resume.update(status='Local review: one-page PDF rendered and visually inspected; extracted text, metrics and three original links checked',visual_reviewed_at=at);write(d/'resume-tailoring.json',resume)
 all_drafts.append((p,draft))
intro=['# January-April 2027: Toronto job outreach','Five named contacts with provider-verified work emails. Three posted-role routes, including one with unconfirmed winter dates, and two speculative staffing inquiries. All are local drafts; no messages or applications submitted. The preferred entry point is a direct email.','## Where I would start','RBC Borealis first because the body of its official posting says September 20, 2026, although the header shows September 21. Waabi is the strongest planning/simulation match, with January and four-month availability still to confirm. Peak Power fits the practical energy direction but has no verified winter vacancy. Kepler is explicitly acceptable geographically and has the exact term, but its embedded requirements are a real gap. ecobee is a speculative practical-software route.','## Contacts','| Company | Contact and relevant role | Work email | Evidence of opportunity |\n|---|---|---|---|']
for p in plans:intro.append('| '+' | '.join([p['company'],p['person']+' - '+p['contact']['title'],p['contact']['email'],p['vacancy_status']])+' |')
intro+=['\n## Location constraint','Toronto only, exclude North York, target roughly 45 minutes from Hanlan Boat Club at 6 Regatta Road. Commutes are not marked verified because travel mode and some assigned work sites remain unknown. Kepler is included by explicit request. A manager\'s location is not necessarily the job\'s location.','\n## Resume tailoring','Three one-page local variants are prepared for Waabi, RBC Borealis and Kepler. The original purple PDF is unchanged. The variants reorder demonstrated work, adjust headlines and shorten less-relevant details. Each account has a resume-tailoring.json recording changes, requirements matched to evidence, and missing requirements. ecobee and Peak Power use the original resume pending a specific role.','Keywords only describe real experience. Kepler\'s Yocto/OpenEmbedded/FreeRTOS requirements remain gaps. General Linux and robotics hardware deployment do not establish embedded Linux expertise. RBC\'s formal submission needs the resume and transcript combined in one PDF; the resume alone is not a complete application. Waabi also requests a transcript.','\n## Source and fit notes']
for p in plans:
 intro.append('### '+p['company']+'\n\n'+p['priority']+'. '+p['owner_basis']+'\n\nWork site: '+p['office']+'\n\nOpen questions: '+'; '.join(p['gaps'])+'.\n\nSources: '+'; '.join('['+('Role posting' if u==p['job_url'] else 'Supporting source')+']('+u+')' for u in p['sources'])+'\n\nEmail verification receipt: '+p['contact']['source_id']+'. Provider verification is not a delivery guarantee.\n\n[Draft](accounts/'+p['id']+'/draft.md) · [Resume fit and changes](accounts/'+p['id']+'/resume-tailoring.json)')
intro+=['\n## Local implementation status','The job-search and resume-tailoring workflow is saved in skills/andrew-email-style/references/job-search.md. This campaign is kept out of the Contract Work cash/deposit pipeline. A dedicated Jobs UI and automated resume-tailoring engine have not been implemented. Research and ready-to-review artifacts are available here.']
(root/'README.md').write_text('\n\n'.join(intro)+'\n')
(root/'five-job-emails.md').write_text('# Five January job emails\n\nLocal review only. Attach the listed resume when sending; nothing has been sent. Work site/commute and specific placement eligibility need confirmation in the conversation.\n\n'+'\n\n'.join('## '+p['company']+' - '+p['person']+'\n\nTo: '+draft['recipient']+'\n\nSubject: '+draft['subject']+'\n\nAttachment: '+draft['attachments'][0]+'\n\n'+draft['body'] for p,draft in all_drafts)+'\n')
print('Finished 5 reviewed local email drafts, 3 visually checked resume variants and sourced job report.')
